fn read_bits(bits:&[bool],offset:usize,n:usize)->N{let mut out=N::zero();for i in 0..n{if bits[offset+i]{out|=N::one()<<i;}}out}
fn literal_witness(m:&Model,d:usize,bits:&[bool])->Value{assert_eq!(bits.len(),5*d+m.c.n+1);let xs=(0..5).map(|i|read_bits(bits,i*d,d)).collect::<Vec<_>>();let r=read_bits(bits,5*d,m.c.n);let sigma=bits[5*d+m.c.n];let hc=m.c.product(&xs);let(h,k,s,trace)=m.recover(&hc,&r,sigma);assert!(trace,"trace residual failed");assert_eq!(m.c.literal(&h,&k,&r,&s,&m.a,&m.b,&m.z,&m.yt),hc,"independent literal norm replay failed");json!({"primary_bits_hex":read_bits(bits,0,bits.len()).to_str_radix(16),"sources":xs.iter().map(|x|x.to_str_radix(16)).collect::<Vec<_>>(),"r":r.to_str_radix(16),"sigma":sigma,"h":h.to_str_radix(16),"k":k.to_str_radix(16),"s":s.to_str_radix(16)})}
fn solve_norm(m:&Model,d:usize,path:&str,seconds:f64,cap:usize)->Value{assert!(seconds>0.);let started=Instant::now();let(a,eq)=build(m,d,8);let h=Hybrid::compile(&a,&eq,2);let(mut s,mut ok)=h.native(path);let before=s.stats();let mut roots=vec![];let mut seen=std::collections::BTreeSet::new();let mut complete=false;let mut last_verdict=Value::Null;while started.elapsed().as_secs_f64()<seconds&&roots.len()<cap{if !ok{complete=true;break;}let remaining=seconds-started.elapsed().as_secs_f64();if remaining<=0.{break;}let(verdict,model)=s.solve(remaining);last_verdict=json!(verdict);if started.elapsed().as_secs_f64()>=seconds{break;}if verdict==0{complete=true;break;}if verdict!=1{break;}let values=model[1..].iter().map(|x|*x==1).collect::<Vec<_>>();let input=values[..a.inputs].to_vec();assert_eq!(values,h.extension(&input),"native full functional extension mismatch");assert!(h.accepts(&values));assert!(a.eval(&input,&eq));let witness=literal_witness(m,d,&input);assert!(seen.insert(input.clone()),"duplicate complete primary assignment");roots.push(witness);let block=(1..=a.inputs).map(|i|if input[i-1]{-(i as i32)}else{i as i32}).collect::<Vec<_>>();ok=s.clause(&block);}let elapsed=started.elapsed().as_secs_f64();if elapsed>=seconds{complete=false;}let exact=if complete{json!(roots.len())}else{Value::Null};json!({"norm_primary_search_complete":complete,"norm_primary_count_exact":exact,"verified_norm_primary_lower_bound":roots.len(),"verified_norm_models":roots,"last_native_verdict":last_verdict,"native_stats_before_search":before,"native_stats_after_search":s.stats(),"external_variables":h.variables,"primary_variables":a.inputs,"affine_support_limit":2,"xor_rows":h.rows.len(),"native_inner_wall_seconds_diagnostic":elapsed,"root_cap":cap,"original_root_count_exact":null,"original_auxiliary_fibers_reconstructed":false,"independent_unsat_certificate":false,"release_gate_claim":false,"novelty_claim":false})}
fn independent_expected(m:&Model,d:usize)->std::collections::BTreeSet<String>{let primary=5*d+m.c.n+1;let mut out=std::collections::BTreeSet::new();for mask in 0..1usize<<primary{let bits=(0..primary).map(|i|mask>>i&1!=0).collect::<Vec<_>>();let xs=(0..5).map(|i|read_bits(&bits,i*d,d)).collect::<Vec<_>>();let r=read_bits(&bits,5*d,m.c.n);let hc=m.c.product(&xs);let(h,k,s,trace)=m.recover(&hc,&r,bits[5*d+m.c.n]);if trace&&m.c.literal(&h,&k,&r,&s,&m.a,&m.b,&m.z,&m.yt)==hc{out.insert(N::from(mask).to_str_radix(16));}}out}
fn search_controls(path:&str)->Value{let mut cases=vec![];let mut assignments=0;for(n,modulus,a,yt)in[(2,7,0,0),(2,7,0,1),(2,7,1,2),(2,7,1,3),(3,11,0,0),(3,11,0,1)]{let m=Model::new(n,N::from(modulus as u32),N::from(a as u32),N::one(),N::one(),N::from(yt as u32));let expected=independent_expected(&m,1);assignments+=1usize<<(5+n+1);let got=solve_norm(&m,1,path,10.,4096);assert_eq!(got["norm_primary_search_complete"],true);let actual=got["verified_norm_models"].as_array().unwrap().iter().map(|r|r["primary_bits_hex"].as_str().unwrap().to_string()).collect::<std::collections::BTreeSet<_>>();assert_eq!(actual,expected);assert_eq!(got["norm_primary_count_exact"],expected.len());cases.push(json!({"n":n,"a":a,"target_y":yt,"complete_models":expected.len()}));}let m=Model::new(2,N::from(7u32),N::zero(),N::one(),N::one(),N::zero());let capped=solve_norm(&m,1,path,5.,1);assert_eq!(capped["norm_primary_search_complete"],false);assert!(capped["norm_primary_count_exact"].is_null());assert_eq!(capped["verified_norm_primary_lower_bound"],1);let expired=solve_norm(&m,1,path,1e-12,4096);assert_eq!(expired["norm_primary_search_complete"],false);assert!(expired["norm_primary_count_exact"].is_null());assert_eq!(expired["verified_norm_primary_lower_bound"],0);json!({"status":"passed","model_cap_is_inconclusive":true,"expired_budget_is_inconclusive":true,"independent_primary_assignments":assignments,"complete_native_sets":cases,"scope":"literal norm oracle, both target signs, a0/a1, GF4/GF8, zero and repeated source coordinates; full native functional extensions replayed"})}
fn target_model(path:&str)->Model{let x:Value=serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();assert_eq!(x["extension_field"]["degree"],83);let basis=x["source_basis_hex"].as_array().unwrap();assert_eq!(basis.len(),18);for(i,v)in basis.iter().enumerate(){assert_eq!(hx(v.as_str().unwrap()),N::one()<<i);}assert!(hx(x["source_offset_hex"].as_str().unwrap_or("0x0")).is_zero());let z=hx(x["target"]["x_hex"].as_str().unwrap());let yt=hx(x["target"]["y_hex"].as_str().unwrap())^&z;Model::new(83,hx(x["extension_field"]["modulus_hex"].as_str().unwrap()),hx(x["curve"]["a_hex"].as_str().unwrap()),hx(x["curve"]["b_hex"].as_str().unwrap()),z,yt)}
pub fn entry(){let args=std::env::args().collect::<Vec<_>>();if args.get(1).is_some_and(|x|x=="controls"){println!("{}",search_controls(args.get(2).expect("library")));return;}let started=Instant::now();let m=target_model(args.get(2).expect("fixture"));let remaining=60.-started.elapsed().as_secs_f64();assert!(remaining>0.);let e=solve_norm(&m,18,args.get(3).expect("library"),remaining,4096);let done=e["norm_primary_search_complete"]==true;let mut result=json!({"schema":"scientific_result_v1","experiment_id":args.get(1).expect("id"),"status":if done{"passed"}else{"inconclusive"},"summary":"Changed limit2 exact norm-primary search with full native extension and independent literal norm replay; original all-roots completeness remains unclaimed.","evidence":e,"next_actions":["Use actual Gaussian/decision statistics to distinguish representation cost from search behavior; do not retry an unchanged timeout.","Require full original S3 ghost/exception/auxiliary closure, independent completeness certification and matched genuine F4/F5/F6 evidence before any8x claim.","If no witness or completeness in60seconds, change source symmetry/coordinates or constraints under a new frozen hypothesis."]});let mut output=result.to_string();if started.elapsed().as_secs_f64()>=70.{result["status"]=json!("inconclusive");result["evidence"]["norm_primary_search_complete"]=json!(false);result["evidence"]["norm_primary_count_exact"]=Value::Null;output=result.to_string();}println!("{output}");}
